#!/usr/bin/env python3

# Phase 1:
#
# Parse all class*.xml files in the Doxygen output directory to extract every 
# <innerclass refid="..."> attribute, then delete the corresponding .rst file 
# generated by breathe-apidoc.
#
# This guarantees that every nested class is documented once, on its parent page.
#
# Phase 2: 
#
# Delete all .rst stub pages for compounds that have no .xml in this project.
# (e.g. std::allocator that Doxygen mentions but does not document)

import os
import sys
import glob
import xml.etree.ElementTree as ET

# Paths can be overridden via command line arguments
# Usage: python3 scripts/post_apidoc.py <doxygen_xml_dir> <breathe_rst_dir>
XML_DIR = sys.argv[1] if len(sys.argv) > 1 else "doxygen_output/xml"
RST_DIR = sys.argv[2] if len(sys.argv) > 2 else "docs/api"

if not os.path.exists(XML_DIR):
    print(f"[post_apidoc] Error: XML directory '{XML_DIR}' does not exist.")
    sys.exit(1)

if not os.path.exists(RST_DIR):
    print(f"[post_apidoc] Error: RST directory '{RST_DIR}' does not exist.")
    sys.exit(1)

# --- Phase 1: Remove standalone RST files for inner classes ---
print(f"[post_apidoc] Scanning XML files in '{XML_DIR}' for <innerclass> references...")

innerclass_refids = set()

for xml_file in glob.glob(os.path.join(XML_DIR, "class*.xml")):
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()

        for inner in root.findall(".//innerclass"):
            refid = inner.get("refid")
            if refid:
                innerclass_refids.add(refid)
    except ET.ParseError:
        print(f"[post_apidoc] Warning: Could not parse XML file '{xml_file}'")
        continue

print(f"[post_apidoc] Found {len(innerclass_refids)} nested class reference(s).")

innerclass_deleted = 0

for refid in innerclass_refids:
    target_filename = f"{refid}.rst"

    for root, _, files in os.walk(RST_DIR):
        if target_filename in files:
            file_path = os.path.join(root, target_filename)
            os.remove(file_path)
            echo_name = os.path.relpath(file_path, RST_DIR)
            print(f"[post_apidoc] Deleted standalone nested RST: {echo_name}")
            innerclass_deleted += 1

# --- Phase 2: Remove RST stub pages with no corresponding XML file ---
print(f"[post_apidoc] Scanning '{RST_DIR}' for orphan RST stubs without XML files...")

orphan_deleted = 0

for root, _, files in os.walk(RST_DIR):
    # -mindepth 2 equivalent: skip top-level RST files directly in RST_DIR
    if root == RST_DIR:
        continue

    for file in files:
        if not file.endswith(".rst"):
            continue

        base_name = file[:-4]  # Strip .rst extension
        corresponding_xml = os.path.join(XML_DIR, f"{base_name}.xml")

        if not os.path.isfile(corresponding_xml):
            file_path = os.path.join(root, file)
            os.remove(file_path)
            echo_name = os.path.relpath(file_path, RST_DIR)
            print(f"[post_apidoc] Deleted orphan RST stub (no XML): {echo_name}")
            orphan_deleted += 1

print(
    f"[post_apidoc] Done. Removed {innerclass_deleted} nested class RST(s) "
    f"and {orphan_deleted} orphan RST stub(s)."
)

